P = json.loads(gzip.decompress(base64.b64decode("".join(BLOB.split()))))
def rd(f):
    with open(f, encoding="utf-8", newline="") as h:
        return h.read()
def wr(f, s):
    os.makedirs(os.path.dirname(f) or ".", exist_ok=True)
    with open(f, "w", encoding="utf-8", newline="\n") as h:
        h.write(s)
if not os.path.isfile("backend/app/state.py"):
    sys.exit("REFUSED: run this from the Quantum-Trader-repository folder")
bad, done = [], []
for f, want in P["guard"].items():
    cur = rd(f).replace("\r\n", "\n")
    if cur == P["full"][f]:
        done.append(f)
    elif hashlib.sha256(cur.encode()).hexdigest() != want:
        bad.append(f)
if bad:
    sys.exit("REFUSED (nothing changed): these files differ from the copies you attached: " + ", ".join(bad))
plan, warn = {}, []
for f, hunks in P["hunks"].items():
    if not os.path.isfile(f):
        warn.append(f"{f}: not found, skipped"); continue
    src = rd(f).replace("\r\n", "\n"); s = src; ok = True
    for old, new in hunks:
        if new in s and old not in s:
            continue  # already applied
        if s.count(old) != 1:
            ok = False; break
        s = s.replace(old, new, 1)
    if not ok and f.endswith("instruments.py") and "\"MAZDOCK\"" not in src:
        line = next((l for l in src.splitlines() if '"ABB": InstrumentSpec(' in l), None)
        if line:
            add = line.split('"ABB"')[0] + '"MAZDOCK": InstrumentSpec("MAZDOCK", "Mazagon Dock", "NFO", "NSE:MAZDOCK", 1900.0, 0.40, 20, 225, 30),'
            s = src.replace(line, line + "\n" + add, 1); ok = True
    if ok and s != src:
        plan[f] = s
    elif not ok:
        warn.append(f"{f}: your copy differs, this part skipped")
stamp = time.strftime("%Y%m%d%H%M%S")
full = {f: v for f, v in P["full"].items() if f not in done}
for f in list(full) + list(plan):
    shutil.copy2(f, f"{f}.pre3547.{stamp}.bak")
for f, s in full.items():
    wr(f, s)
for f, s in plan.items():
    wr(f, s)
for f, s in P["new"].items():
    wr(f, s)
for w in warn:
    print("WARN", w)
print("v3.5.47 applied OK (backups: *.pre3547.%s.bak)" % stamp)
